update notice
set deleted_flag = true
where notice_id = #{noticeId}

mapper.select:
select , notice_type.notice_type_name, (select count(*) from notice_view_record where notice_view_record.employee_id = #{requestEmployeeId} and notice_view_record.notice_id = notice.notice_id) as viewFlag from notice left join notice_type on notice.notice_type_id = notice_type.notice_type_id
( notice.notice_id in (select notice_visible_range.notice_id from notice_visible_range where ( notice_visible_range.data_type = #{departmentDataType}
and notice_visible_range.data_id in
#{item}
) or ( notice_visible_range.data_type = #{employeeDataType} and notice_visible_range.data_id = #{requestEmployeeId} ) ) or notice.all_visible_flag = true )
and notice.deleted_flag = #{deletedFlag} and notice.publish_time < now()
AND notice_type.notice_type_id = #{query.noticeTypeId}
AND ( INSTR(notice.title,#{query.keywords}) OR INSTR(notice.author,#{query.keywords}) OR INSTR(notice.document_number,#{query.keywords}) OR INSTR(notice.source,#{query.keywords}) )
AND DATE_FORMAT(notice.publish_time, '%Y-%m-%d') >= DATE_FORMAT(#{query.publishTimeBegin}, '%Y-%m-%d')
AND DATE_FORMAT(notice.publish_time, '%Y-%m-%d') <= DATE_FORMAT(#{query.publishTimeEnd}, '%Y-%m-%d')
AND viewFlag = 0
order by notice.publish_time desc

select * from ( select , notice_type.notice_type_name, (select count(*) from notice_view_record where notice_view_record.employee_id = #{requestEmployeeId} and notice_view_record.notice_id = notice.notice_id) as viewFlag from notice left join notice_type on notice.notice_type_id = notice_type.notice_type_id
notice.notice_id in (select notice_visible_range.notice_id from notice_visible_range where (notice_visible_range.data_type = #{departmentDataType}
and notice_visible_range.data_id in
#{item}
) or ( notice_visible_range.data_type = #{employeeDataType} and notice_visible_range.data_id = #{requestEmployeeId} ) )
and notice.all_visible_flag = true and notice.deleted_flag = #{deletedFlag} and notice.publish_time < now()
AND notice_type.notice_type_id = #{query.noticeTypeId}
AND ( INSTR(notice.title,#{query.keywords}) OR INSTR(notice.author,#{query.keywords}) OR INSTR(notice.documentNumber,#{query.keywords}) OR INSTR(notice.source,#{query.keywords}) )
AND DATE_FORMAT(notice.publish_time, '%Y-%m-%d') >= DATE_FORMAT(#{query.publishTimeBegin}, '%Y-%m-%d')
AND DATE_FORMAT(notice.publish_time, '%Y-%m-%d') <= DATE_FORMAT(#{query.publishTimeEnd}, '%Y-%m-%d')
) t where viewFlag = 0 order by t.publish_time desc

select notice_view_record.*, employee.actual_name as employeeName, department.department_name from notice_view_record left join employee on employee.employee_id = notice_view_record.employee_id left join department on department.department_id = employee.department_id where notice_id = #{queryForm.noticeId}
AND ( INSTR(employee.actual_name,#{queryForm.keywords}) OR INSTR(notice_view_record.first_ip,#{queryForm.keywords}) OR INSTR(notice_view_record.first_user_agent,#{queryForm.keywords}) OR INSTR(notice_view_record.last_ip,#{queryForm.keywords}) OR INSTR(notice_view_record.last_user_agent,#{queryForm.keywords}) )
and department.department_id = #{queryForm.departmentId}
order by notice_view_record.update_time desc,notice_view_record.create_time desc

select count(*)
from notice_view_record
where notice_id = #{noticeId}
  and employee_id = #{employeeId}

mapper.update:
update notice_view_record
set page_view_count = page_view_count + 1,
    last_ip         = #{ip},
    last_user_agent = #{userAgent}
where notice_id = #{noticeId}
  and employee_id = #{employeeId}

update notice
set page_view_count = page_view_count + #{pageViewCountIncrement},
    user_view_count = user_view_count + #{userViewCountIncrement}
where notice_id = #{noticeId}
